package com.personal.jobagent.identity;
import org.springframework.web.bind.annotation.*; import java.time.Duration; import java.util.*;
@RestController @RequestMapping("/api/v1/identity") public class IdentityController {private final IdentityService service;private final CredentialVault vault;public IdentityController(IdentityService s,CredentialVault v){service=s;vault=v;} public record IdentityRequest(UUID profileId,String email,String domain,String credential){} public record SessionRequest(UUID applicationId,String domain){} @PostMapping("/identities") public Map<String,Object> create(@RequestBody IdentityRequest r){String ref=r.credential()==null?null:vault.store(r.credential(),Duration.ofHours(1));return Map.of("identityId",service.create(r.profileId(),r.email(),r.domain(),ref));} @PostMapping("/sessions") public Map<String,Object> session(@RequestBody SessionRequest r){return Map.of("sessionId",service.startSession(r.applicationId(),r.domain()));} @GetMapping("/sessions/{id}") public Map<String,Object> get(@PathVariable UUID id){return service.session(id);} @PostMapping("/sessions/{id}/hard-stop") public Map<String,Object> stop(@PathVariable UUID id,@RequestBody Map<String,String> b){return Map.of("changed",service.hardStop(id,b.getOrDefault("reason","unspecified")));} }